// Generated by `drift_dev make-migrations`, then extended with data checks
// for each upgrade.
import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:memuki/domain/ids.dart';
import 'package:memuki/storage/converters.dart';
import 'package:memuki/storage/database.dart';
import 'package:memuki/storage/sync/hlc.dart';

import 'generated/schema.dart';

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('simple database migrations', () {
    // Verifies every schema upgrade without data.
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = MemukiDatabase(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  test('v1 to v2 stamps existing rows and keeps their data', () async {
    final schema = await verifier.schemaAt(1);
    final collection = CollectionId.generate();
    final deck = DeckId.generate();
    final noteType = NoteTypeId.generate();
    final field = FieldDefinitionId.generate();
    final template = StudyCardTemplateId.generate();
    final note = NoteId.generate();
    final card = StudyCardId.derive(note, template);
    final event = ReviewEventId.generate();
    Uint8List bytes(Object id) => Uint8List.fromList(
      // Every ID type is a UUID string at runtime.
      const IdConverter<String>(_identity).toSql(id as String),
    );

    final raw = schema.rawDatabase;
    raw.execute('INSERT INTO collections VALUES (?, ?)', [
      bytes(collection),
      'Japanese',
    ]);
    raw.execute('INSERT INTO decks VALUES (?, ?, NULL, ?)', [
      bytes(deck),
      bytes(collection),
      'Vocab',
    ]);
    raw.execute('INSERT INTO note_types VALUES (?, ?, ?)', [
      bytes(noteType),
      bytes(collection),
      'Basic',
    ]);
    raw.execute('INSERT INTO field_definitions VALUES (?, ?, 0, ?, ?)', [
      bytes(field),
      bytes(noteType),
      'Front',
      'text',
    ]);
    raw.execute('INSERT INTO study_card_templates VALUES (?, ?, 0, ?)', [
      bytes(template),
      bytes(noteType),
      'Card 1',
    ]);
    raw.execute('INSERT INTO notes VALUES (?, ?, ?, NULL, NULL)', [
      bytes(note),
      bytes(collection),
      bytes(noteType),
    ]);
    raw.execute('INSERT INTO note_fields VALUES (?, ?, ?)', [
      bytes(note),
      bytes(field),
      '猫',
    ]);
    raw.execute('INSERT INTO study_cards VALUES (?, ?, ?, ?, ?)', [
      bytes(card),
      bytes(collection),
      bytes(note),
      bytes(template),
      bytes(deck),
    ]);
    raw.execute(
      'INSERT INTO review_events VALUES '
      "(?, ?, 'review', 1000, 'good', NULL, NULL, NULL, NULL, 'sm2', 1, 1)",
      [bytes(event), bytes(card)],
    );

    final now = DateTime.utc(2026, 10, 29, 12);
    final db = MemukiDatabase(schema.newConnection(), now: () => now);
    addTearDown(db.close);

    final device = await db.select(db.device).getSingle();
    final initial = Hlc(now.millisecondsSinceEpoch, 0, device.node);
    expect(device.lastHlc, initial);

    final deckRow = await db.select(db.decks).getSingle();
    expect(deckRow.name, 'Vocab');
    expect(deckRow.hlc, initial);
    expect(deckRow.deleted, isFalse);
    expect((await db.select(db.noteFields).getSingle()).value, '猫');
    expect((await db.select(db.noteFields).getSingle()).hlc, initial);
    expect((await db.select(db.reviewEvents).getSingle()).hlc, initial);
    expect(await db.select(db.outbox).get(), isEmpty);

    // The clock continues after the migration's timestamp.
    expect(db.clock.tick() > initial, isTrue);
  });
}

String _identity(String value) => value;
